@Injectable()
export class UniversalAuthGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const type = context.getType(); // 'http' | 'ws' | 'rpc'

    if (type === 'http') {
      const request = context.switchToHttp().getRequest<Request>();
      return this.validateToken(request.headers.authorization);
    } else if (type === 'ws') {
      const client = context.switchToWs().getClient<Socket>();
      return this.validateToken(client.handshake.auth.token);
    }
    return true;
  }
}

