// Cursor-based pagination với TypeORM QueryBuilder:
async getFeed(cursor?: string, limit = 20) {
  const qb = this.postRepo.createQueryBuilder('post')
    .orderBy('post.createdAt', 'DESC')
    .addOrderBy('post.id', 'DESC')
    .take(limit + 1); // Lấy thêm 1 để check hasNextPage

  if (cursor) {
    const { createdAt, id } = decodeCursor(cursor);
    qb.where('(post.createdAt, post.id) < (:createdAt, :id)', { createdAt, id });
  }

  const items = await qb.getMany();
  const hasNextPage = items.length > limit;
  if (hasNextPage) items.pop();

  const nextCursor = hasNextPage ? encodeCursor(items[items.length - 1]) : null;
  return { items, nextCursor, hasNextPage };
}

