@WebSocketGateway({ cors: { origin: '*' }, namespace: 'orders' })
export class OrderGateway implements OnGatewayConnection, OnGatewayDisconnect {
  @WebSocketServer()
  server: Server;

  constructor(private jwtService: JwtService) {}

  async handleConnection(client: Socket) {
    try {
      const token = client.handshake.auth?.token;
      const payload = await this.jwtService.verifyAsync(token);
      client.data.user = payload; // Lưu thông tin auth vào socket session
      client.join(`user_${payload.sub}`);
    } catch {
      client.disconnect();
    }
  }

  @SubscribeMessage('joinOrderRoom')
  handleJoinRoom(@ConnectedSocket() client: Socket, @MessageBody() orderId: string) {
    client.join(`order_${orderId}`);
    return { status: 'joined', orderId };
  }
}

