export class AuthService {
  async refreshTokens(userId: string, refreshToken: string) {
    const user = await this.userRepo.findOneBy({ id: userId });
    if (!user || !user.refreshTokenHash) throw new ForbiddenException('Access Denied');

    const matches = await argon2.verify(user.refreshTokenHash, refreshToken);
    if (!matches) {
      // Phát hiện dùng token cũ/giả mạo: Xóa toàn bộ token session của user
      await this.userRepo.update(userId, { refreshTokenHash: null });
      throw new ForbiddenException('Compromised token detected! Please login again.');
    }

    const tokens = await this.generateTokens(user.id, user.email);
    await this.updateRefreshTokenHash(user.id, tokens.refreshToken);
    return tokens;
  }
}

