@Injectable()
export class ApiKeyGuard implements CanActivate {
  constructor(private tenantService: TenantService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const req = context.switchToHttp().getRequest();
    const apiKey = req.headers['x-api-key'];
    if (!apiKey) throw new UnauthorizedException('API Key missing');

    const tenant = await this.tenantService.validateApiKey(apiKey);
    if (!tenant) throw new UnauthorizedException('Invalid API Key');

    // Lưu vào AsyncLocalStorage để dùng xuyên suốt không cần Scope.REQUEST
    TenantContext.setTenantId(tenant.id);
    req.tenant = tenant;
    return true;
  }
}

@Injectable()
export class ProductService {
  constructor(
    @Inject(CACHE_MANAGER) private cache: Cache,
    private repo: ProductRepository,
  ) {}

  async getProduct(id: string): Promise<Product> {
    const cacheKey = `product:${id}`;
    const cached = await this.cache.get<Product>(cacheKey);
    if (cached) return cached;

    const product = await this.repo.findById(id);
    if (product) {
      // Set TTL 1 giờ + jitter ngẫu nhiên 0-60 giây
      const jitter = Math.floor(Math.random() * 60);
      await this.cache.set(cacheKey, product, (3600 + jitter) * 1000);
    }
    return product;
  }

  async updateProduct(id: string, dto: UpdateProductDto) {
    const updated = await this.repo.update(id, dto);
    await this.cache.del(`product:${id}`); // Invalidate ngay lập tức
    return updated;
  }
}

