@Injectable()
export class InterestCalculationScheduler {
  constructor(private readonly redlock: Redlock, private readonly service: InterestService) {}

  @Cron(CronExpression.EVERY_DAY_AT_MIDNIGHT)
  async handleDailyInterest() {
    const lockKey = `locks:daily-interest:${new Date().toISOString().slice(0, 10)}`;
    let lock;
    try {
      // Giành quyền thực thi độc quyền trong 30 phút
      lock = await this.redlock.acquire([lockKey], 30 * 60 * 1000);
      await this.service.calculateAndDisburse();
    } catch (err) {
      // Không lấy được lock chứng tỏ pod khác đang chạy -> Bỏ qua an toàn
      console.log('Task already acquired by another pod, skipping.');
    } finally {
      if (lock) await lock.release();
    }
  }
}

