@UseFilters(new ExceptionFilter())
@Controller()
export class PaymentConsumer {
  @EventPattern('payment_process')
  async handlePayment(@Payload() data: any, @Ctx() context: RmqContext) {
    const channel = context.getChannelRef();
    const originalMsg = context.getMessage();

    try {
      await this.paymentService.charge(data);
      channel.ack(originalMsg); // Thành công -> Xác nhận đã xử lý
    } catch (error) {
      const retryCount = originalMsg.properties.headers['x-retry-count'] || 0;
      if (retryCount >= 3) {
        // Vượt quá số lần thử -> Đẩy vào DLQ (không requeue)
        channel.nack(originalMsg, false, false);
      } else {
        // Tái xuất với delay / retry counter tăng dần
        this.retryService.publishWithBackoff(data, retryCount + 1);
        channel.ack(originalMsg);
      }
    }
  }
}

