@Injectable()
export class QueueConsumer {
  constructor(private readonly moduleRef: ModuleRef) {}

  async processJob(jobData: JobPayload) {
    // 1. Tạo một Context ID giả lập độc lập
    const contextId = ContextIdFactory.create();

    // 2. Gắn thông tin tenant/user vào sub-tree nếu cần
    this.moduleRef.registerRequestByContextId({ tenantId: jobData.tenantId }, contextId);

    // 3. Phân giải Request-scoped service an toàn
    const auditLogger = await this.moduleRef.resolve<AuditLoggerService>(
      AuditLoggerService,
      contextId,
    );

    await auditLogger.logAction(jobData.action);
  }
}
